#!/usr/bin/env bash
# 🦉 #685 — deterministic Nova glTF pipeline (single source of truth).
#
#   nova_src.gltf  ──►  gltf-transform optimize (Meshopt + KTX2)  ──►  nova.glb
#
# The Blender Nova rig (#686) exports nova_src.gltf; until then the procedural
# placeholder is regenerated by scripts/team/make_nova_src.mjs. The output
# nova.glb is committed to apps/kid/public/assets/ and precached offline.
#
# Compression (design doc 3d-nova-pipeline.md §1.1):
#   * Meshopt — geometry + morph targets + animation (preserves vertex order;
#     Draco would break skinning/morph fidelity)
#   * KTX2 — requires the `ktx` CLI (KTX-Software: `brew install ktx`). When
#     present, the encoder auto-selects ETC1S (base-color) vs UASTC (normal/ORM);
#     if #686's textures need a hand-tuned per-slot split, move the ktx2 step
#     to the @gltf-transform/core scripting API with explicit slots.
#
# Target: nova.glb < 2 MiB (else the Workbox 5 MiB bump — tracked in #691).
# Idempotent: same input → re-runnable; fixed tool versions via lockfile.
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"

SRC="${1:-apps/kid/public/assets/nova_src.gltf}"
OUT="${2:-apps/kid/public/assets/nova.glb}"
GT="apps/kid/node_modules/.bin/gltf-transform"
MAX_BYTES=$((2 * 1024 * 1024))   # < 2 MiB target

echo "── glTF pipeline: $SRC → $OUT"
[ -f "$SRC" ] || { echo "✖ missing source $SRC (run make_nova_src.mjs or drop in the Blender export)" >&2; exit 1; }
[ -x "$GT" ] || { echo "✖ gltf-transform CLI missing — pnpm --filter kid add -D @gltf-transform/cli" >&2; exit 1; }

# KTX2 is the target, but the `ktx` encoder binary must be on PATH. The
# procedural placeholder has no textures (materials pruned), so it degrades to
# Meshopt-only cleanly; #686's textured model REQUIRES `ktx` — fail loudly then.
ARGS=(optimize "$SRC" "$OUT" --compress meshopt --verbose)
if command -v ktx >/dev/null 2>&1; then
  echo "  ✓ ktx encoder found — KTX2 texture compression ON"
  ARGS+=(--texture-compress ktx2 --texture-size 2048)
else
  echo "  ⚠ ktx encoder NOT found (brew install ktx) — skipping KTX2 textures."
  echo "    (fine for the texture-less placeholder; required once #686 ships textures)"
fi

"$GT" "${ARGS[@]}"

SIZE=$(stat -f%z "$OUT" 2>/dev/null || stat -c%s "$OUT")
echo "── nova.glb = $((SIZE / 1024)) KiB"
if [ "$SIZE" -gt "$MAX_BYTES" ]; then
  echo "  ✖ ${SIZE} B > 2 MiB — target missed. Options:" >&2
  echo "    1. reduce the model (see design doc budget)" >&2
  echo "    2. #691 will raise Workbox maximumFileSizeToCacheInBytes to 5 MiB" >&2
  exit 1
fi
echo "  ✓ ${SIZE} B < 2 MiB — offlinable under the Workbox default."
